function formatUsd(microUsd) {
  if (!Number.isSafeInteger(microUsd))
    throw new Error("usd amount must be an integer microUSD value");
  const sign = microUsd < 0 ? "-" : "";
  const abs = Math.abs(microUsd);
  const whole = Math.floor(abs / 1e6);
  const fraction = String(abs % 1e6).padStart(6, "0");
  return sign + whole + "." + fraction;
}
