async function revertChange(options) {
  throwIfAborted2(options.signal);
  const change = options.store.readChange(options.changeId);
  if (change === null)
    throw new Error("CHANGE_NOT_FOUND: " + options.changeId);
  const revertable = change.state === "APPLIED" || change.state === "RECOVERY_REQUIRED" || change.state === "REVERTING" || change.state === "PREPARED" || change.state === "APPLYING" || change.state === "CONFLICT";
  if (!revertable)
    return { state: change.state, reason: "CHANGE_NOT_APPLIED" };
  const inDoubt = change.state === "PREPARED" || change.state === "APPLYING";
  const binding = options.store.readBinding(change.bindingId);
  if (binding === null)
    throw new Error("BINDING_NOT_FOUND: " + change.bindingId);
  return withWriterLease(options.store, async () => {
    throwIfAborted2(options.signal);
    assertWorkspaceIdentity(binding);
    const target = resolveInside(binding.workspaceRoot, change.workflowPath);
    assertRegularFile(target);
    const currentText = readFileSync8(target, "utf8");
    const currentHash = textHash(currentText);
    if (currentHash !== change.after.hash) {
      if (currentHash === change.before.hash) {
        if (inDoubt) {
          options.store.saveChange({ ...change, state: "NOT_APPLIED", updatedAt: iso2(options.now) });
          discardBackup(options.store, change.changeId);
          return { state: "NOT_APPLIED", reason: "TARGET_UNCHANGED" };
        }
        options.store.saveChange({ ...change, state: "REVERTED", updatedAt: iso2(options.now) });
        const warnings = options.store.appendSummaryEvent({ type: "reverted", changeId: change.changeId }, options.now);
        return { state: "REVERTED", reason: null, ...warnings.length > 0 ? { warnings } : {} };
      }
      options.store.saveChange({ ...change, state: "CONFLICT", updatedAt: iso2(options.now) });
      return { state: "CONFLICT", reason: "CURRENT_BYTES_CHANGED" };
    }
    const maintenance = acquireStoreLock(options.store, "maintenance", STORE_WRITE_LOCK_WAIT_MS, { clock: options.clock, ids: options.ids });
    try {
      const backup = options.store.readBackup(change.changeId);
      if (backup === null) {
        options.store.saveChange({ ...change, state: "RECOVERY_REQUIRED", updatedAt: iso2(options.now) });
        return { state: "RECOVERY_REQUIRED", reason: "BACKUP_UNAVAILABLE" };
      }
      if (backup.manifest.beforeHash !== change.before.hash || textHash(backup.beforeText) !== change.before.hash) {
        options.store.saveChange({ ...change, state: "RECOVERY_REQUIRED", updatedAt: iso2(options.now) });
        return { state: "RECOVERY_REQUIRED", reason: "BACKUP_HASH_MISMATCH" };
      }
      const recheck = readFileSync8(target, "utf8");
      if (textHash(recheck) !== change.after.hash) {
        options.store.saveChange({ ...change, state: "CONFLICT", updatedAt: iso2(options.now) });
        return { state: "CONFLICT", reason: "CURRENT_BYTES_CHANGED" };
      }
      throwIfAborted2(options.signal);
      if (change.state !== "REVERTING") {
        options.store.saveChange({ ...change, state: "REVERTING", updatedAt: iso2(options.now) });
      }
      const mode = statSync5(target).mode;
      const restoredHash = await replaceAtomically(target, backup.beforeText, mode, change.after.hash, binding, options.signal);
      if (restoredHash !== change.before.hash) {
        options.store.saveChange({ ...change, state: "RECOVERY_REQUIRED", updatedAt: iso2(options.now) });
        return { state: "RECOVERY_REQUIRED", reason: "RESTORE_HASH_MISMATCH" };
      }
      options.store.saveChange({ ...change, state: "REVERTED", updatedAt: iso2(options.now) });
      const warnings = options.store.appendSummaryEvent({ type: "reverted", changeId: change.changeId }, options.now);
      return { state: "REVERTED", reason: null, ...warnings.length > 0 ? { warnings } : {} };
    } finally {
      maintenance.release();
    }
  }, { clock: options.clock, ids: options.ids });
}

// src/core/patch/approval.ts
init_constants();
function approvalConfirmation(plan) {
  return plan.planDigest.slice(-12);
}
function approvePlan(input) {
  const initial = input.store.readPlan(input.planId);
  if (initial === null)
    throw new Error("PLAN_NOT_FOUND: " + input.planId);
  const lock = acquireStoreLock(input.store, "approve-" + initial.plan.planId, APPROVE_LOCK_WAIT_MS, { clock: input.clock, ids: input.ids });
  try {
    return approveLocked(input);
  } finally {
    lock.release();
  }
}
function approveLocked(input) {
  const stored = input.store.readPlan(input.planId);
  if (stored === null)
    throw new Error("PLAN_NOT_FOUND: " + input.planId);
  const plan = stored.plan;
  const previous = input.store.readNonce(plan.planId);
  if (input.store.listChanges().some((change) => change.planId === plan.planId && change.state !== "NOT_APPLIED")) {
    throw new Error("PLAN_ALREADY_USED: " + input.planId);
  }
  if (plan.status.state === "approved") {
    if (previous === null || previous.nonceId !== plan.status.approvalNonceId || previous.planDigest !== plan.planDigest) {
      throw new Error("NONCE_INVALID: approval record missing or mismatched");
    }
    const until = Date.parse(previous.createdAt) + (input.approvalTtlSeconds ?? DEFAULT_APPROVAL_TTL_SECONDS) * 1000;
    if (!Number.isFinite(until) || input.now.getTime() < until)
      throw new Error("PLAN_ALREADY_APPROVED: " + input.planId);
  }
  if (input.now.getTime() >= Date.parse(plan.payload.expiresAt))
    throw new Error("PLAN_EXPIRED: " + plan.payload.expiresAt);
  if (input.confirmation.trim() !== approvalConfirmation(plan))
    throw new Error("NONCE_INVALID: confirmation does not match the plan digest");
  const at = input.now.toISOString().replace(/\.\d{3}Z$/, "Z");
  const nonce = {
    nonceId: "n_" + digestOf({ planId: plan.planId, digest: plan.planDigest, at }).slice("sha256:".length, "sha256:".length + 24),
    planDigest: plan.planDigest,
    createdAt: at,
    subjectId: input.subjectId,
    channel: input.channel
  };
  const approved = {
    ...plan,
    status: {
      state: "approved",
      revision: plan.status.revision + 1,
      previewedAt: plan.status.previewedAt ?? at,
      approvedAt: at,
      approvalNonceId: nonce.nonceId
    }
  };
  input.store.saveNonce(plan.planId, nonce);
  try {
    input.store.updatePlanStatus(plan.planId, approved.status, plan.status.revision);
  } catch (error) {
    if (previous !== null)
      input.store.saveNonce(plan.planId, previous);
    else
      input.store.consumeNonce(plan.planId, nonce.nonceId);
    throw error;
  }
  const warnings = input.store.appendSummaryEvent({ type: "approved", planId: plan.planId, nonceId: nonce.nonceId, channel: input.channel }, input.now);
  return { plan: approved, nonce, ...warnings.length > 0 ? { warnings } : {} };
}

